import { uuidRegex } from "../../utils/regex";
import { checkUrlMatches } from "../../utils/url";
import { ashbyAlertUrlMap } from "../../utils/urlMapping";

/**
 * Matches
 *  - /interview-briefings/:interviewId/feedback
 */
export const isScorecardUrlTabView = (
  path = window.location.pathname,
): boolean => {
  const [interviewBriefings, interviewId, feedback, ...rest] = path
    .toLowerCase()
    .split("/")
    .filter((s) => !!s);

  return (
    interviewBriefings === "interview-briefings" &&
    feedback === "feedback" &&
    rest.length === 0 &&
    interviewId.match(uuidRegex) !== null
  );
};

/**
 * Matches
 *  - /interview-briefings/:interviewId(/anything)?
 *  - also includes a check to localstorage to determine the UI mode the user has selected
 */
export const isScorecardUrlColumnView = (
  path = window.location.pathname,
): boolean => {
  const [interviewBriefings, interviewId, ...rest] = path
    .toLowerCase()
    .split("/")
    .filter((s) => !!s);

  const isColumn =
    localStorage.getItem("InterviewBriefingFeedbackView") === "column";

  return (
    isColumn &&
    interviewBriefings === "interview-briefings" &&
    rest.length <= 1 &&
    interviewId.match(uuidRegex) !== null
  );
};

/**
 * Matches
 *  - (/anything)/right-side/candidates/:candidateId/applications/:applicationId/(subtab)
 *
 * There are several different paths a user can take to launch a popup to submit
 * a feedback form on these URLs. They all require user interaction to launch
 * and do not update the URL when launched
 */
export const isCandidateFeedbackUrl = (
  path = window.location.pathname,
): boolean => {
  const [
    subtab,
    applicationId,
    applications,
    candidateId,
    candidates,
    rightSide,
  ] = path
    .toLowerCase()
    .split("/")
    .reverse() // this is necessary to get the "popup" data from the url
    .filter((s) => !!s);

  return (
    !!subtab &&
    applicationId.match(uuidRegex) !== null &&
    applications === "applications" &&
    candidateId.match(uuidRegex) !== null &&
    candidates === "candidates" &&
    rightSide === "right-side"
  );
};

/**
 * Matches
 *  - *\/candidates/:id/*
 */
export const isCandidateUrl = (path = window.location.pathname): boolean => {
  const pathParts = path
    .toLowerCase()
    .split("/")
    .filter((s) => !!s);

  return pathParts.some(
    (path, idx) =>
      path === "candidates" && pathParts[idx + 1]?.match(uuidRegex),
  );
};

export const isAlertUrl = (path = window.location.pathname): boolean => {
  return checkUrlMatches(path, ashbyAlertUrlMap);
};

export type URLMatchInfo = {
  isCandidatePage: boolean;
  isScorecardPage: boolean;
  isAlertPage: boolean;
  /**
   * A normalized version of the page URL, `null` if this
   * is not a page we should run on
   */
  tabUrl: string | null;
};

export const getUrlMatchInfo = (
  path = window.location.pathname,
): URLMatchInfo => {
  const isCandidatePage = isCandidateUrl(path);
  const isScorecardPage =
    isScorecardUrlTabView(path) || isScorecardUrlColumnView(path);
  const isAlertPage = isAlertUrl(path);
  const shouldShowDrawer = isCandidatePage || isScorecardPage || isAlertPage;

  return {
    isCandidatePage,
    isScorecardPage,
    isAlertPage,
    tabUrl: shouldShowDrawer ? normalizeTabUrl(path) : null,
  };
};

export const normalizeTabUrl = (path = window.location.pathname): string => {
  let normalizedPath = "";

  if (isScorecardUrlTabView(path)) {
    normalizedPath = path;
  } else if (isScorecardUrlColumnView(path)) {
    const ignorePaths = ["briefing", "all-feedback"];
    const filteredPath = path
      .toLowerCase()
      .split("/")
      .filter((s) => !!s && !ignorePaths.some((p) => s === p))
      .join("/");

    normalizedPath = `/${filteredPath}/feedback`;
  } else if (isCandidateUrl(path)) {
    const pathParts = path
      .toLowerCase()
      .split("/")
      .filter((s) => !!s);

    const i = pathParts.findIndex(
      (path, idx) =>
        path === "candidates" && pathParts[idx + 1]?.match(uuidRegex),
    );
    normalizedPath = `/${pathParts.slice(i, i + 2).join("/")}`;
  } else if (isAlertUrl(path)) {
    if (path.startsWith("/candidates/pipeline")) {
      normalizedPath = "/candidates/pipeline";
    } else if (path.startsWith("/candidate-searches")) {
      normalizedPath = "/candidate-searches";
    } else {
      normalizedPath = path;
    }
  }

  if (normalizedPath) {
    return `${window.location.origin}${normalizedPath}${window.location.search}`;
  }

  return "";
};

export class CandidateFeedbackPopupObserver {
  private onOpened: (node: Element, tabUrl: string) => void;

  private onClosed: (tabUrl: string) => void;

  private connected = false;

  /**
   * Manages a `MutationObserver` to watch for when a popup with
   * a feedback form is opened
   */
  constructor({
    onOpened,
    onClosed,
  }: {
    /** Called when the popup is opened with a feedback form */
    onOpened: (node: Element, tabUrl: string) => void;
    /** Called when the feedback form popup is closed */
    onClosed: (tabUrl: string) => void;
  }) {
    this.onOpened = onOpened;
    this.onClosed = onClosed;
  }

  private observer = new MutationObserver((mutations) => {
    const { tabUrl } = getUrlMatchInfo();
    if (!tabUrl) return;

    const added = mutations.find((m) =>
      Array.from(m.addedNodes).some((node) =>
        node.textContent?.match(/(submit|edit) feedback/i),
      ),
    );
    if (added) {
      this.onOpened(added.target as Element, tabUrl);
      return;
    }

    const removed = mutations.some((m) =>
      Array.from(m.removedNodes).some((node) =>
        node.textContent?.match(/(submit|edit) feedback/i),
      ),
    );
    if (removed) {
      this.onClosed(tabUrl);
    }
  });

  connect(rootEl: Element): void {
    if (this.connected) return;
    this.observer.observe(rootEl, { childList: true });
    this.connected = true;
  }

  disconnect(): void {
    this.observer.disconnect();
    this.connected = false;
  }
}
