/**
 * Handles showing and hiding the BrightHire sidepanel across all Ashby pages
 */
import {
  closeDrawerToast,
  openDrawerToast,
  setupDrawer,
} from "../../utils/drawer";
import {
  addPassiveMessageListener,
  sendMessageWithTabId,
} from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { getUrlMatchInfo, type URLMatchInfo } from "./utils";

let previousMatch: URLMatchInfo | null = null;

const checkPage = (): void => {
  const matchInfo = getUrlMatchInfo();
  const { tabUrl } = matchInfo;

  if (tabUrl) {
    const forceReload = shouldReload(matchInfo);
    setupDrawer({ tabUrl, forceReload });
    openDrawerToast();
    if (forceReload) {
      sendMessageWithTabId({ action: "drawerLoading" });
    }
  } else {
    closeDrawerToast();
  }

  previousMatch = matchInfo;
};

const shouldReload = ({
  tabUrl,
  isCandidatePage,
  isScorecardPage,
  isAlertPage,
}: URLMatchInfo): boolean => {
  if (!previousMatch) return true;

  if (tabUrl && !previousMatch.tabUrl) return true;
  if (isCandidatePage && !previousMatch.isCandidatePage) return true;
  if (isScorecardPage && !previousMatch.isScorecardPage) return true;
  if (isAlertPage && !previousMatch.isAlertPage) return true;

  return false;
};

onDocumentLoaded(() => {
  checkPage();
});

addPassiveMessageListener(({ message }) => {
  if (message.action === "tabUrlChanged") {
    checkPage();
  }
});
